-- Restore only as part of a reviewed full rollback transaction.
create or replace function public.ca_v2_save_person(p_cong_id text,p_person jsonb,p_shared boolean default false) returns jsonb language plpgsql security definer set search_path='' as $$declare person_id text=p_person->>'id';email text=lower(btrim(coalesce(p_person->>'email','')));g public.service_groups;expected jsonb;begin perform ca_private.v2_require(p_cong_id,array['admin']);perform pg_advisory_xact_lock(hashtextextended('publisher-login:'||p_cong_id,0));if length(coalesce(person_id,'')) not between 1 and 100 or length(btrim(coalesce(p_person->>'name',''))) not between 1 and 300 then raise exception 'Publisher name and ID required';end if;if email<>'' and(email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' or length(email)>254) then raise exception 'Invalid email';end if;if exists(select 1 from public.publishers where id=person_id and (cong_id<>p_cong_id or transferred_at is not null)) then raise exception 'Publisher cannot be modified in this congregation' using errcode='42501';end if;if email<>'' and not p_shared and exists(select 1 from public.congregation_access where cong_id=p_cong_id and role='publisher' and active and congregation_access.email=ca_v2_save_person.email and publisher_id<>person_id) then raise exception 'Confirm household reporting or choose a different email';end if;if nullif(btrim(p_person->>'group'),'') is not null then select * into g from public.service_groups where cong_id=p_cong_id and name_key=lower(regexp_replace(btrim(p_person->>'group'),'\s+',' ','g')) and archived_at is null;if not found then raise exception 'Choose an existing group';end if;end if;insert into public.publishers(id,cong_id,name,group_id,service_group,phone,address,gender) values(person_id,p_cong_id,btrim(p_person->>'name'),g.id,g.name,left(coalesce(p_person->>'phone',''),30),left(coalesce(p_person->>'address',''),2000),coalesce(p_person->>'gender','Male')) on conflict(id) do update set name=excluded.name,group_id=excluded.group_id,service_group=excluded.service_group,phone=excluded.phone,address=excluded.address;expected=public.get_publisher_login(p_cong_id,person_id);perform public.set_publisher_login(p_cong_id,person_id,expected,email);return jsonb_build_object('id',person_id,'saved',true);end $$;
